import pandas as pd

def count_apples_and_oranges(boxes: pd.DataFrame, chests: pd.DataFrame) -> pd.DataFrame:
    merged = boxes.merge(chests, on='chest_id', how='left', suffixes=('_box', '_chest'))
    apples = merged['apple_count_box'].fillna(0) + merged['apple_count_chest'].fillna(0)
    oranges = merged['orange_count_box'].fillna(0) + merged['orange_count_chest'].fillna(0)
    return pd.DataFrame({'apple_count': [apples.sum()], 'orange_count': [oranges.sum()]})

