#include <bits/stdc++.h>
using namespace std;

pair<long long, long long> countApplesAndOranges(
    vector<array<int, 4>>& boxes,
    vector<array<int, 3>>& chests) {
    unordered_map<int, pair<int, int>> chest;
    for (auto& c : chests) chest[c[0]] = {c[1], c[2]};
    long long apples = 0, oranges = 0;
    for (auto& b : boxes) {
        auto it = chest.find(b[1]);
        int ca = it != chest.end() ? it->second.first : 0;
        int co = it != chest.end() ? it->second.second : 0;
        apples += b[2] + ca;
        oranges += b[3] + co;
    }
    return {apples, oranges};
}

