import java.util.*;

class Solution {
    public long[] countApplesAndOranges(int[][] boxes, int[][] chests) {
        Map<Integer, int[]> chest = new HashMap<>();
        for (int[] c : chests) chest.put(c[0], new int[]{c[1], c[2]});
        long apples = 0, oranges = 0;
        for (int[] b : boxes) {
            int[] c = chest.get(b[1]);
            apples += b[2] + (c == null ? 0 : c[0]);
            oranges += b[3] + (c == null ? 0 : c[1]);
        }
        return new long[]{apples, oranges};
    }
}

