var countApplesAndOranges = function(boxes, chests) {
    const chest = new Map(chests.map((c) => [c[0], [c[1], c[2]]]));
    let apples = 0, oranges = 0;
    for (const [, cid, a, o] of boxes) {
        const c = chest.get(cid);
        apples += a + (c ? c[0] : 0);
        oranges += o + (c ? c[1] : 0);
    }
    return [apples, oranges];
};
